import { relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { toString } from 'mdast-util-to-string';
import { visit } from 'unist-util-visit';

const docsDir = fileURLToPath(new URL('../docs/', import.meta.url));
const sourceOrigin = 'https://handbook.local';
const explicitAnchor = /\s+\{\s*#([\w-]+)\s*\}$/;
const fenceLanguages = {
  apt: 'text',
  alloy: 'text',
  conf: 'ini',
  cron: 'text',
  dockerignore: 'text',
  fstab: 'text',
  gradle: 'groovy',
  pam: 'text',
  proguard: 'text',
  ssh: 'ssh-config',
};

// Keep the IDs generated by Python Markdown so existing bookmarks still work.
function legacySlug(text) {
  return text.normalize('NFKD')
    .replace(/[^\x00-\x7F]/g, '')
    .replace(/[^\w\s-]/g, '')
    .trim()
    .toLowerCase()
    .replace(/[-\s]+/g, '-');
}

function escapeHtml(text) {
  return text.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
}

export function handbookMarkdown({ base }) {
  return (tree, file) => {
    if (!file.path) return;
    const page = relative(docsDir, file.path);
    if (page.startsWith('../')) return;

    const sourceUrl = new URL(page, sourceOrigin);
    const ids = new Set();
    const title = tree.children[0]?.depth === 1 ? tree.children[0] : null;

    visit(tree, 'heading', (heading) => {
      const tail = heading.children.at(-1);
      const explicit = tail?.type === 'text' && tail.value.match(explicitAnchor);
      if (explicit) tail.value = tail.value.slice(0, explicit.index);

      // A colon-delimited Android task name can be parsed as a Markdown directive.
      const position = heading.position;
      const text = position && heading.children.some((child) => child.type === 'textDirective')
        ? String(file.value).slice(position.start.offset, position.end.offset).replace(/^#+\s+/, '')
        : toString(heading);
      let id = explicit ? explicit[1] : legacySlug(text);
      while (!id || ids.has(id)) {
        id = /_\d+$/.test(id) ? id.replace(/\d+$/, (n) => Number(n) + 1) : `${id}_1`;
      }
      ids.add(id);
      heading.data ??= {};
      heading.data.hProperties = { ...heading.data.hProperties, id };
    });

    // Starlight displays the entry title above the content. Keep the old H1 fragment.
    if (title) {
      tree.children[0] = { type: 'html', value: `<span id="${title.data.hProperties.id}" aria-hidden="true"></span>` };
    }

    visit(tree, ['link', 'definition'], (link) => {
      if (!/^[^#?]+\.mdx?(?=$|[?#])/i.test(link.url)) return;
      const url = new URL(link.url, sourceUrl);
      if (url.origin !== sourceOrigin) return;

      const route = url.pathname.replace(/\.mdx?$/, '').replace(/\/index$/, '');
      link.url = `${base}${route}/${url.search}${url.hash}`;
    });

    visit(tree, 'code', (code, index, parent) => {
      if (Object.hasOwn(fenceLanguages, code.lang)) code.lang = fenceLanguages[code.lang];
      if (code.lang !== 'mermaid' || index === undefined || !parent) return;
      parent.children[index] = {
        type: 'html',
        value: `<pre class="handbook-mermaid">${escapeHtml(code.value)}</pre>`,
      };
    });
  };
}
